import json
import pandas as pd

# Check chain to country consistency
with open('json/gasstations.json') as f:
    data = json.load(f)

stations = data['records']
station_chain = {s['GasStationID']: s['ChainID'] for s in stations}
chain_country = {}

for s in stations:
    chain = s['ChainID']
    country = s['Country']
    if chain not in chain_country:
        chain_country[chain] = set()
    chain_country[chain].add(country)

# Check if any chain has multiple countries
multi_country_chains = {k: v for k, v in chain_country.items() if len(v) > 1}
print(f'Chains with multiple countries: {len(multi_country_chains)}')
if multi_country_chains:
    for chain, countries in list(multi_country_chains.items())[:10]:
        print(f'  Chain {chain}: {countries}')

# If all chains are single-country, we could potentially map by ChainID
single_country_chains = {k: list(v)[0] for k, v in chain_country.items() if len(v) == 1}
print(f'\nChains with single country: {len(single_country_chains)}')
print(f'Single country chains: {sorted(single_country_chains.items())[:20]}')

